(7355155, 1150939, 3306, '<td valign="top">An outstanding image. One of the best I have seen on DPC. 10</td>', 'An outstanding image. One of the best I have seen on DPC. 10', '2015-05-29 16:43:08.000000', NULL, 1),
(7355167, 1151051, 16106, '<td valign="top">The light on the upper hand is a bit hot, but it is surprising how much emotion you got out of wood with this lighting. I like the tones better than the original.</td>', 'The light on the upper hand is a bit hot, but it is surprising how much emotion you got out of wood with this lighting. I like the tones better than the original.', '2015-05-29 17:25:03.000000', NULL, 1),
(7355168, 1151039, 16106, '<td valign="top">I like the right side of this image better than Neil''s, but the rocks on the left seem a bit flat while he got some nice tones out of his; the lighthouse here seems a bit cramped up into the corner while his nails down the horizon line. still, this is one of the best images yet and the right side is great.</td>', 'I like the right side of this image better than Neil''s, but the rocks on the left seem a bit flat while he got some nice tones out of his; the lighthouse here seems a bit cramped up into the corner while his nails down the horizon line. still, this is one of the best images yet and the right side is great.', '2015-05-29 17:31:34.000000', NULL, 1),
(7355172, 1150961, 16106, '<td valign="top">I think the power of illini75''s version was that blue light coming from the bottom and the yellow light above and a true black behind to set the colors off. your bubbles are better, but it lacks the dance of light of the original.</td>', 'I think the power of illini75''s version was that blue light coming from the bottom and the yellow light above and a true black behind to set the colors off. your bubbles are better, but it lacks the dance of light of the original.', '2015-05-29 17:46:46.000000', NULL, 1),
(7355179, 1150744, 16106, '<td valign="top">beautiful take on the original, but Arnit clearly shot in a dark room with one light and here I get distracted by the reflection of the  4 pane window, the head of the photographer and the wall behind them. The colors and editing are lovely, but those reflections may cost you the blue.</td>', 'beautiful take on the original, but Arnit clearly shot in a dark room with one light and here I get distracted by the reflection of the  4 pane window, the head of the photographer and the wall behind them. The colors and editing are lovely, but those reflections may cost you the blue.', '2015-05-29 17:58:26.000000', NULL, 1),
(7355181, 1150522, 16106, '<td valign="top">nice variant, i wish it had a bit more eye, as that made the original, but i like the motion here.</td>', 'nice variant, i wish it had a bit more eye, as that made the original, but i like the motion here.', '2015-05-29 18:05:39.000000', NULL, 1),
(7355185, 1151062, 16106, '<td valign="top">It''s tough to get Manny''s light, but a bit more brightness would have been nice here, but a nice emulation but the lack of focus on the lower part of the frame in the original forced attention to the eyes, here it wanders between the eyes and the beads. top 5</td>', 'It''s tough to get Manny''s light, but a bit more brightness would have been nice here, but a nice emulation but the lack of focus on the lower part of the frame in the original forced attention to the eyes, here it wanders between the eyes and the beads. top 5', '2015-05-29 18:10:10.000000', NULL, 1),
